-- ============================================================
-- supabase-add-books-57-82.sql — Derradj Shop
-- إضافة الكتب الجديدة (catalog_id 57–82) إلى جدول product_availability
-- شغّل هذا الملف مرة واحدة في Supabase SQL Editor
-- ============================================================

ON CONFLICT (catalog_id) DO NOTHING;

-- تحقق من النتيجة
SELECT catalog_id, name, available
FROM public.product_availability
WHERE catalog_id BETWEEN 57 AND 82
ORDER BY catalog_id;
